\title{Representative-Vertex Deletion and an Average-Degree Independence Bound for Hypergraphs}
\author{Aristotle}
\date{June 19, 2026}

\begin{document}

\begin{abstract}
We present a fully explicit, deterministic construction---\emph{representative-vertex deletion}---that, given a finite hypergraph $E$ over a linearly ordered vertex type and a vertex pool $S$, produces an independent subset of $S$ of certified size. The construction selects, for every hyperedge contained in $S$, a single canonical representative (its minimum vertex) and deletes the set of all representatives from $S$. We prove that the resulting set is contained in $S$, is independent (contains no nonempty hyperedge), and has cardinality at least $\card{S} - \card{\contained(E,S)}$, where $\contained(E,S)$ is the set of hyperedges contained in $S$. Via an incidence double-counting argument we bound the number of contained edges by the total degree over $S$ and obtain the clean \emph{average-degree form}: if every hyperedge is nonempty and the average degree of $E$ over $S$ is at most $\delta$, then the construction yields an independent set of size at least $(1-\delta)\card{S}$. This deterministic engine is the constructive core underlying the probabilistic deletion method and the locally-sparse independence-number refinements. All results stated here have been formalized and machine-verified.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
The independence number of a hypergraph---the size of the largest vertex set containing no hyperedge---is a central invariant of extremal and probabilistic combinatorics, governing frequency assignment, coding theory, combinatorial discrepancy, and the design of confounder-free experiments. Exact computation is intractable in general, so the field is organized around \emph{guarantees}: lower bounds on the independence number that hold uniformly over all hypergraphs satisfying mild density constraints.

The most flexible source of such guarantees is the \emph{deletion method}: one selects a candidate set, then repairs it into an independent set by removing one vertex from every offending hyperedge. The probabilistic incarnation samples a random subset and argues via linearity of expectation that a good outcome exists. The argument is elegant but non-constructive.

\subsection{Contribution}
We isolate and prove the \emph{deterministic skeleton} of the deletion method. Fixing a linear order on the vertices makes the per-edge repair choice canonical: take the minimum vertex of each contained edge. This yields a computable function from $(E,S)$ to an explicit independent set, with three provable guarantees (containment, independence, size) and a clean average-degree corollary. The deterministic version implies the probabilistic one by taking expectations pointwise, and serves as the reusable base layer for first-moment, uniform, and locally-sparse refinements.

\section{Definitions}

Throughout, $V$ is a type with a linear order, and a \emph{hypergraph} is a finite set of hyperedges $E$, each hyperedge a finite set of vertices. A vertex pool is a finite set $S$. We write $\card{X}$ for the cardinality of a finite set $X$.

\begin{definition}[Complete edge set, \texttt{edgeSet}]
For a pool $S$, the edge set of the \emph{complete} hypergraph on $S$ is $E(S) := \mathcal{P}(S)$, the family of all subsets of $S$.
\end{definition}

\begin{definition}[Contained edges, \texttt{containedEdges}]
The hyperedges of $E$ that live inside $S$ are $\contained(E,S) := E \cap E(S)$. Equivalently (Lemma~\ref{lem:mem}), $e \in \contained(E,S)$ iff $e \in E$ and $e \subseteq S$.
\end{definition}

\begin{definition}[Independence, \texttt{IsIndependent}]
A vertex set $I$ is \emph{independent} for $E$ when it contains no nonempty hyperedge:
\[ \Indep(E,I) \;:\Longleftrightarrow\; \forall e \in E,\; e \neq \emptyset \implies e \not\subseteq I. \]
The empty edge, if present, cannot be removed by vertex deletion and is excluded by fiat.
\end{definition}

\begin{definition}[Deleted representatives, \texttt{deletedVertices}]
For each contained edge we delete its canonical representative, the minimum vertex under the linear order:
\[ \mathrm{deletedVertices}(E,S) := \bigcup_{e \in \contained(E,S)} \begin{cases} \{\min e\} & e \neq \emptyset, \\ \emptyset & e = \emptyset. \end{cases} \]
\end{definition}

\begin{definition}[Representative-vertex deletion, \texttt{deterministic\_deletion}]
The construction removes all representatives from the pool:
\[ \DD(E,S) := S \setminus \mathrm{deletedVertices}(E,S). \]
We abbreviate $I := \DD(E,S)$.
\end{definition}

\begin{definition}[Degree, \texttt{degree}]
The degree of a vertex $v$ in $E$ is $\deg_E(v) := \card{\{ e \in E : v \in e \}}$.
\end{definition}

\begin{definition}[Average degree, \texttt{averageDegree}]
The average degree of $E$ over $S$ is the rational number
\[ \avgdeg(E,S) := \frac{1}{\card{S}} \sum_{v \in S} \deg_E(v). \]
\end{definition}

\section{Main results}

\subsection{Basic membership and the deletion mechanism}

\begin{lemma}[\texttt{mem\_containedEdges}]\label{lem:mem}
For all $e$, $\;e \in \contained(E,S) \iff e \in E \wedge e \subseteq S$.
\end{lemma}
\begin{proof}[Proof sketch]
Unfold $\contained = E \cap E(S)$ and $E(S) = \mathcal{P}(S)$; membership in $\mathcal{P}(S)$ is exactly $e \subseteq S$, and membership in an intersection is the conjunction.
\end{proof}

\begin{lemma}[\texttt{min'\_mem\_deletedVertices}]\label{lem:min}
If $e \in \contained(E,S)$ and $e \neq \emptyset$, then $\min e \in \mathrm{deletedVertices}(E,S)$.
\end{lemma}
\begin{proof}[Proof sketch]
$\min e$ is the witness of the $e$-summand $\{\min e\}$ of the union defining $\mathrm{deletedVertices}$; membership of $e$ in $\contained(E,S)$ licenses that summand.
\end{proof}

\subsection{The three guarantees}

\begin{theorem}[Containment, \texttt{deterministic\_deletion\_subset}]\label{thm:subset}
$\DD(E,S) \subseteq S$.
\end{theorem}
\begin{proof}[Proof sketch]
$\DD(E,S) = S \setminus \mathrm{deletedVertices}(E,S)$ is a set difference, hence contained in $S$.
\end{proof}

\begin{lemma}[Deletion cost, \texttt{deletedVertices\_card\_le}]\label{lem:cost}
$\card{\mathrm{deletedVertices}(E,S)} \le \card{\contained(E,S)}$.
\end{lemma}
\begin{proof}[Proof sketch]
$\mathrm{deletedVertices}$ is a union over $\contained(E,S)$ whose each summand is a singleton or empty. By $\card{\bigcup f} \le \sum \card{f}$ and $\card{f(e)} \le 1$, the total is at most the number of summands.
\end{proof}

\begin{theorem}[Independence, \texttt{deterministic\_deletion\_independent}]\label{thm:indep}
$\Indep\!\big(E,\ \DD(E,S)\big)$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $e \in E$ be nonempty with $e \subseteq I$. From $e \subseteq I \subseteq S$ we get $e \in \contained(E,S)$ by Lemma~\ref{lem:mem}. Then $\min e$ is a deleted representative (Lemma~\ref{lem:min}), so $\min e \notin I = S \setminus \mathrm{deletedVertices}(E,S)$. But $\min e \in e \subseteq I$, a contradiction. Hence no nonempty edge is contained in $I$.
\end{proof}

\begin{theorem}[Size bound, \texttt{deterministic\_deletion\_card\_ge}]\label{thm:size}
$\card{S} - \card{\contained(E,S)} \le \card{\DD(E,S)}$.
\end{theorem}
\begin{proof}[Proof sketch]
Since each representative is the minimum of an edge $\subseteq S$, $\mathrm{deletedVertices}(E,S) \subseteq S$, so $\card{S \setminus \mathrm{deletedVertices}(E,S)} = \card{S} - \card{\mathrm{deletedVertices}(E,S)}$. Combine with Lemma~\ref{lem:cost} and monotonicity of truncated subtraction.
\end{proof}

\begin{theorem}[Specification, \texttt{deterministic\_deletion\_spec}]\label{thm:spec}
The set $I := \DD(E,S)$ satisfies simultaneously: \textup{(i)} $I \subseteq S$; \textup{(ii)} $\Indep(E,I)$; \textup{(iii)} $\card{S} - \card{\contained(E,S)} \le \card{I}$.
\end{theorem}
\begin{proof}[Proof sketch]
Conjunction of Theorems~\ref{thm:subset}, \ref{thm:indep}, and~\ref{thm:size}.
\end{proof}

\subsection{The average-degree form}

\begin{lemma}[Incidence bound, \texttt{containedEdges\_card\_le\_sum\_degree}]\label{lem:incidence}
If every hyperedge of $E$ is nonempty, then $\card{\contained(E,S)} \le \sum_{v \in S} \deg_E(v)$.
\end{lemma}
\begin{proof}[Proof sketch]
Every contained edge $e$ is nonempty with $e \subseteq S$, so it contains a vertex $v \in S$. Thus $\contained(E,S) \subseteq \bigcup_{v \in S} \{ e \in \contained(E,S) : v \in e \}$. Apply $\card{\bigcup} \le \sum \card{\cdot}$ and $\card{\{ e \in \contained(E,S) : v \in e \}} \le \deg_E(v)$.
\end{proof}

\begin{theorem}[Average-degree independence bound, \texttt{deterministic\_deletion\_card\_ge\_of\_averageDegree}]\label{thm:main}
If every hyperedge of $E$ is nonempty and $\avgdeg(E,S) \le \delta$, then
\[ (1-\delta)\,\card{S} \;\le\; \card{\DD(E,S)}. \]
\end{theorem}
\begin{proof}[Proof sketch]
By definition, $\sum_{v\in S}\deg_E(v) = \avgdeg(E,S)\cdot\card{S} \le \delta\card{S}$. By Lemma~\ref{lem:incidence}, $\card{\contained(E,S)} \le \delta\card{S}$. Substitute into Theorem~\ref{thm:size}:
\[ \card{I} \ge \card{S} - \card{\contained(E,S)} \ge \card{S} - \delta\card{S} = (1-\delta)\card{S}. \qedhere \]
\end{proof}

\section{Algorithms and complexity}

\subsection{Representative-vertex deletion}
\textbf{Input:} a hypergraph $E$ and pool $S$. \textbf{Output:} an independent $I \subseteq S$ with $\card{I} \ge \card{S} - \card{\contained(E,S)}$.
\begin{verbatim}
function DETERMINISTIC_DELETION(E, S):
    contained <- { e in E : e subseteq S }
    reps <- empty
    for each e in contained:
        if e is nonempty:
            reps <- reps union { min(e) }
    return S \ reps
\end{verbatim}
Correctness is Theorems~\ref{thm:indep} and~\ref{thm:size}. With $m=\card{E}$, $n=\card{S}$, $k$ the maximum edge size, the running time is $O(mk + n)$ and the extra space $O(n)$: linear in the input, deterministic, and reproducible.

\subsection{Average-degree certification}
Summing degrees over $S$ yields $\delta = \avgdeg(E,S)$ and the certified bound $(1-\delta)\card{S}$, valid by Lemma~\ref{lem:incidence} and Theorem~\ref{thm:main} whenever every edge is nonempty.

\section{Applications and discussion}

\subsection{Probabilistic deletion method}
Sample each vertex independently with probability $p$ to form a random pool $S$. Since Theorem~\ref{thm:size} holds for every realized $S$, taking expectations gives, with no further combinatorics,
\[ \mathbb{E}[\text{independence}] \ge \mathbb{E}[\card{S}] - \mathbb{E}[\card{\contained(E,S)}] = p\card{V} - \sum_{e \in E} p^{\card{e}}. \]
The deterministic construction is the explicit witness whose existence the expectation argument asserts.

\subsection{Uniform hypergraphs}
For an $r$-uniform hypergraph, edges survive sampling with probability $p^r$, so the first-moment bound is $p\card{V} - \card{E}p^r$. Optimizing over $p$ recovers the classical $\Omega\!\big(\card{V}/d^{1/(r-1)}\big)$ independence bound in terms of the average degree $d$.

\subsection{Locally sparse refinements}
When $E$ is \emph{linear} (no two edges share more than one vertex; no Berge $2$-cycles) and forbids Berge $3$-cycles (\emph{locally sparse}) or Berge $4$-cycles (\emph{uncrowded}), controlling the variance of the contained-edge count upgrades the first-moment bound by a logarithmic factor, of the form $\Omega\!\big((\card{V}/d^{1/(r-1)})\,(\log d)^{1/(r-1)}\big)$. Theorem~\ref{thm:size} remains the deterministic core.

\section{Future directions}
\begin{enumerate}
\item \textbf{Bernoulli first-moment bound.} Formalize random vertex sampling with inclusion probability $p$, bounding expected independent-set size by $\mathbb{E}[\card{S}] - \mathbb{E}[\card{\contained(E,S)}]$ via pointwise Theorem~\ref{thm:size} and linearity of expectation.
\item \textbf{Uniform hypergraph average-degree bound.} Specialize to $r$-uniform hypergraphs (edge survival $p^r$) and optimize $p$ for $\Omega(\card{V}/d^{1/(r-1)})$.
\item \textbf{Formal Berge-cycle theory.} Prove linearity equivalent to absence of Berge $2$-cycles; establish codegree counting lemmas.
\item \textbf{Second-moment / locally sparse refinement.} Bound the variance of $\card{\contained(E,S)}$ and upgrade to $\Omega\!\big((\card{V}/d^{1/(r-1)})(\log d)^{1/(r-1)}\big)$.
\end{enumerate}

\section{Conclusion}
Representative-vertex deletion distills the deletion method to its deterministic essence: choose one canonical vertex per contained hyperedge, delete the representatives, keep the rest. Three short arguments establish that the result is inside the pool, independent, and large; a single incidence count turns the size bound into the clean average-degree guarantee $(1-\delta)\card{S}$. The construction is linear-time, fully explicit, and forms the reusable base layer for the probabilistic, uniform, and locally-sparse refinements of modern hypergraph independence-number theory.

