from fractions import Fraction

def contained_edges(E, S):
    return {e for e in E if e <= S}

def deterministic_deletion(E, S):
    reps = {min(e) for e in contained_edges(E, S) if e}
    return frozenset(S - reps)

def degree(E, v):
    return sum(1 for e in E if v in e)

def is_independent(E, I):
    return all(not (e and e <= I) for e in E)

S = frozenset(range(1, 17))
E = {frozenset({1,2,3}), frozenset({4,5,6})}
I = deterministic_deletion(E, S)
delta = Fraction(sum(degree(E, v) for v in S), len(S))
print('survivors      :', sorted(I), '|I| =', len(I))
print('avg degree d   :', delta)
print('bound (1-d)|S| :', (1 - delta) * len(S))
print('independent?   :', is_independent(E, I))
print('|I| >= (1-d)|S|:', Fraction(len(I)) >= (1 - delta) * len(S))

