fails = 0
for _ in range(5000):
    n = rng.randint(4, 20)
    S = frozenset(range(1, n + 1))
    E = set()
    for _ in range(rng.randint(0, 2 * n)):
        k = rng.randint(1, min(4, n))
        E.add(frozenset(rng.sample(range(1, n + 1), k)))
    I = deterministic_deletion(E, S)
    c = len(contained_edges(E, S))
    delta = Fraction(sum(degree(E, v) for v in S), len(S)) if S else Fraction(0)
    ok = (I <= S and is_independent(E, I) and len(I) >= len(S) - c
          and Fraction(len(I)) >= (1 - delta) * len(S))
    if not ok:
        fails += 1
print('instances:', 5000, ' violations:', fails)

